import json
import sys
from pathlib import Path

root = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(root / 'tools'))
from en_r24 import load, write_en

voices = {
    'tove': ('Tove', 'Quiet, plain conversational English. Few words, unhurried warmth, tolerance for cold and discomfort. Her own place and other people\'s right to rest draw firm boundaries.', 'Distance outdoors opens into sitting by the door, Harben barracks and lodging memories, choosing to sleep inside, and shared rest without making tomorrow\'s choices compulsory.'),
    'urda': ('Priest Urda', 'Unhurried, warm, talkative English with measured formality and gentle humor. Soup and welcome precede debate. Closeness brings personal doubts rather than louder sermons.', 'Jokes and meals open into Tarn Valley faith, the ten years before heresy could sound like praise, nights of doubt, receiving help and keeping a place even without answers.'),
    'zahar': ('Zahar', 'Rough, direct conversational English. Brief sentences and practical actions precede stories. Strength never means unlimited labor or insensitivity to pain.', 'Practical silence opens into carrying shared loads, the number 417 in Drum, conscription and choosing the revolt, then asking for help and quiet company without surrendering her name.'),
    'sorel': ('Sorel', 'Cool, concise conversational English. Prices, ownership and exceptions are stated directly. Quiet company and longing do not erase her financial boundaries.', 'Prices lead into voluntary discounts, exile and keeping the name Aenwyn, missing the forest, and visiting without a purchase or ledger.'),
    'teiris': ('Teiris', 'Courteous, curious conversational English. Observation prompts layered questions; unfamiliar slang arrives slightly late and imperfectly. Personal insight quiets and shortens her speech.', 'Polite investigation opens into a personal notebook, envoy memories, differences between forest instructions and her own wishes, and remembering companions beyond official reports.'),
    'tika': ('Tika', 'Loud, exuberant conversational English before a crowd; small, hesitant clauses when alone together. Use occasional faltering openings without caricature. Praise folds her ears and delays her answer.', 'Crowd laughter opens into unperformed stories, repayment and frightening freedom, then chosen quiet companionship and laughter that needs no audience.'),
    'ornel': ('Ornel', 'Quiet, observant conversational English. City noises, stone roads and unfamiliar routines prompt precise questions. Many-legged creatures interrupt her composure and bring direct requests for help.', 'Reserve opens into questions about life outside the forest, Silverbough Watch memories, admitting fear of insects and choosing a place outside the forest without discarding home.'),
    'saya': ('Saya', 'Brief, calm conversational English. Short complete thoughts, often with omitted subjects where natural. Hands act before explanations; gratitude and knitting slow her down. Boundaries remain quiet and firm.', 'Practical silence opens into remembered kindness, beginning to knit when repayment was impossible, personally giving handmade gifts and visiting empty-handed without turning company into debt.'),
    'selva': ('Selva', 'Level, practical, mostly formal English with occasional conversational warmth. Pay and duties are explicit; meals, familiar shops and rest are personal choices rather than further contracts.', 'Terms lead into favors outside contract, life from Kern to Marento, arena memories and choosing to live here. Familiarity brings shared meals without surrendering boundaries.'),
    'marceline': ('Marceline', 'Low, courteous formal English. She tends others first and hesitates over personal questions. Procedures borrowed from fiction and awkward claims about doctrinal books remain sincere rather than mocking.', 'Procedural distance opens into doubts about judgment, the day she escorted a sentence, sharing a private book, and commitments in her own words that put people before rigid observance.'),
    'miko': ('Miko', 'Unhurried, kind conversational English. Busy hands and practical observations accompany calm, firm boundaries. Rest and asking for care become ordinary personal needs.', 'Matter-of-fact treatment opens into barracks childhood, guild work, difficult choices when medicine runs short, and admitting her habit of postponing her own needs.'),
    'naran': ('Naran', 'Quick, playful conversational English. Questions test prices and motives; jokes turn the bargain. Ledger and road metaphors stay concrete. Closeness allows slower smiles and direct requests.', 'Initial bargaining opens into freely offered information, tribal and guild ledgers, growing up paying for knowledge, and choosing to remain without losing the freedom to leave.'),
    'lavinia': ('Lavinia', 'Courteous, careful English with a mix of formal statements and softer conversational requests. Permits and checks reassure her; they do not replace personal choices.', 'Procedural distance opens into memories of receiving her permit, questions about Judith and Tove, reaching toward injured people, and resting without paperwork.'),
    'levia': ('Levia', 'Quiet, hesitant conversational English. Short clauses and tentative questions gradually become clear refusals and requests. Fear remains compatible with agency and companionship.', 'Avoided eyes and broken phrases become chosen proximity, memories of the broken crystal ball, and voluntary use of power with the continuing freedom to stop.'),
    'lynette': ('Lynette', 'Warm, persistent conversational English. Rice, relief funds and shared meals are concrete concerns. Gentleness includes firm boundaries about recipients\' privacy and her own needs.', 'Fundraising and practical care open into the canal shelter and name book, difficult faith, personal rest and keeping her own portion without justifying it as future service.'),
    'hildegard': ('Sir Hildegard', 'Courteous, precise formal English. Commands break off and become requests. Responsibility includes the rear guard and increasingly her own need for rest.', 'Public roles give way to shared decisions, border service memories and the personal choice to remain. Greater trust allows asking for relief and company.'),
    'jorund': ('Jorund', 'Polite, restrained formal English with full verb forms. Plans, clauses and consent remain exact. Personal preferences and family loyalties are stated without apology.', 'Terms and conditions open into preferences, growing up as an elder\'s granddaughter, and keeping unwritten promises. Closeness does not erase family interests.'),
    'judith': ('Judith', 'Confident conversational English with contractions and pointed questions. Magical curiosity quickens her speech. Pride remains as she learns to include people in her plans.', 'Initial distance opens into research and expulsion memories. Deeper trust permits uncertainty, thanks, shared review and choosing people before an answer.'),
}

for cid in sys.argv[1:]:
    path, data = load(cid)
    en = data['en']
    en['display'] = {k: v.lstrip('\ufeff').replace('Bergholt', 'Berghold').replace('the Borderlands', 'the March').replace('Aenwin', 'Aenwyn') for k,v in en['display'].items()}
    title, register, stages = voices[cid]
    en['speech'] = {'register': register, 'address_terms': {'companion_to_player': [], 'player_to_companion': title}, 'stage_relaxation': stages, 'extension': 'Extend established boundaries and voluntary requests without adding canonical facts for unspecified stages.'}
    write_en(path, en)
    print(cid, len(en['display']))
